 save(phase='running',lastProgressAt=datetime.datetime.now(datetime.timezone.utc).isoformat(),nextAction='Wait for permission/question/error/completion')
 print(json.dumps({'sessionId':S['sessionId'],'status':api('/session/status').get(S['sessionId'])}))
elif sys.argv[1]=='watch':
 seenbusy=S['phase']=='running'
 while True:
